async function trust(member){
  const value=await fingerprint(member),key='vesper-key:'+app.state.me.id+':'+member.id,previous=localStorage.getItem(key);
  if(previous&&previous!==value)throw new Error('La clé de '+initials(member)+' a changé. Vérifiez son identité avant de continuer.');
  if(!previous)localStorage.setItem(key,value);return value;
}
