function communityAllowed(){return !app.state?.account.verificationRequired||app.state.account.emailVerified;}
function connectEvents(){
  app.events?.close();app.events=new EventSource('/api/events');
  app.events.onmessage=event=>{
    let value;try{value=JSON.parse(event.data);}catch{return;}
    if(value.type==='state')scheduleRefresh();
    if(value.type==='typing'){typingPresence.update(value);renderTyping();}
    if(value.type==='messages'){if(value.action==='created'){typingPresence.update({channelId:value.channelId,userId:value.authorId,active:false});renderTyping();}sounds.receive(value,{me:app.state.me.id,status:app.state.me.status}).catch(()=>{});if(value.action==='created'&&value.authorId!==app.state.me.id&&value.channelId!==app.channelId)app.unread.set(value.channelId,(app.unread.get(value.channelId)||0)+1);if(value.channelId===app.channelId||app.cache.has(value.channelId))syncMessage(value).catch(showError);if(value.channelId!==app.channelId&&(!space()||space().kind==='dm'))scheduleRefresh();}
    if(value.type==='voice'){for(const item of app.state.spaces){const room=item.channels.find(room=>room.id===value.channelId);if(room)room.voiceUsers=value.users;}if(app.voice.channelId===value.channelId)app.voice.sync(value.users);renderChannels();renderVoice();}
    if(value.type==='signal')app.voice.signal(value).catch(showError);
    if(value.type==='voice-kick'){app.voice.leave().catch(showError);toast('Vous avez quitté le salon vocal.');}
    if(value.type==='session-revoked')endSession('Votre session a été révoquée. Reconnectez-vous.').catch(showError);
  };
  app.events.onopen=()=>{if(channel()?.kind==='text')loadMessages(false,true).catch(showError);};
  app.events.onerror=()=>{if(!$('app').hidden)toast('Connexion temps réel interrompue. Reconnexion automatique…');};
}
