async function refresh(){
  const updated=await api('/api/state');if(!app.identity)return;app.state=updated;
  if(app.spaceId!==null&&!space()){app.spaceId=null;app.channelId=null;}
  if(app.spaceId!==null&&!channel())app.channelId=space()?.channels.find(room=>room.kind==='text')?.id||null;
  if(app.voice.channelId&&!updated.spaces.some(item=>item.channels.some(room=>room.id===app.voice.channelId)))await app.voice.leave();
  render();if(!communityAllowed()){app.events?.close();app.events=null;securityModal();return;}await loadMessages();if(!app.events)connectEvents();
}
