document.addEventListener('click',event=>{const target=event.target.closest?.('button');if(!target||target.disabled||localStorage.getItem('vesper-motion')==='reduced')return;const bounds=target.getBoundingClientRect(),ripple=element('span','button-ripple');ripple.style.left=(event.detail?event.clientX-bounds.left:bounds.width/2)+'px';ripple.style.top=(event.detail?event.clientY-bounds.top:bounds.height/2)+'px';ripple.setAttribute('aria-hidden','true');target.append(ripple);setTimeout(()=>ripple.remove(),480);});
